public class DefensiveSpecial69Check{static void ok(boolean b,String s){if(!b)throw new AssertionError(s);}public static void main(String[]args)throws Exception{Thread.setDefaultUncaughtExceptionHandler((t,e)->{e.printStackTrace();System.exit(1);});Thread.currentThread().setName("GameThread");System.setProperty("solo.mode","true");Server.startServerless();Player p=WeaponsEquipment69Check.actor();InstancedArea a=new InstancedArea(InstanceConfiguration.CLOSE_ON_EMPTY,new Boundary(3300,3830,3330,3855)){public void onDispose(){}};a.add(p);BossRoutesCheck.at(p,3312,3840,a.getHeight());ok(p.getPosition().inMulti(),"Multi test arena");List<NPC> mobs=new ArrayList<>();for(int i=0;i<13;i++){NPC n=new NPC(Npcs.GOBLIN,new Position(p.getX()+1+i%3,p.getY()+i/3,a.getHeight()));a.add(n);n.getHealth().setMaximumHealth(5000);n.getHealth().reset();n.getCombatDefinition().setLevel(NpcCombatSkill.ATTACK,100);n.getCombatDefinition().setLevel(NpcCombatSkill.STRENGTH,100);mobs.add(n);}p.playerEquipment[3]=21015;p.playerEquipmentN[3]=1;p.getCombatConfigs().setAttackStyle(0);p.bulwarkReadyTick=0;p.playerBonus[Bonus.ATTACK_CRUSH.ordinal()]=1000000;p.specAmount=10;p.usingSpecial=true;p.setSpellId(-1);p.autocasting=false;p.attacking.attackEntity(mobs.get(0));ok(p.specAmount==5&&p.getDamageQueue().getQueue().size()==11,"Bulwark 50percent/two main/nine secondary hits: "+p.specAmount+"/"+p.getDamageQueue().getQueue().size());for(int i=0;i<12;i++)p.getDamageQueue().execute();ok(mobs.get(0).getCombatDefinition().getLevel(NpcCombatSkill.ATTACK)==95,"Dinh main drain once");int tagged=0;for(NPC n:mobs)if(n.underAttack)tagged++;ok(tagged==10,"Dinh target cap/tag "+tagged);p.getCombatConfigs().setAttackStyle(1);p.bulwarkReadyTick=0;p.getDamageQueue().getQueue().clear();p.attackTimer=0;p.usingSpecial=false;p.attacking.attackEntity(mobs.get(0));ok(p.getDamageQueue().getQueue().isEmpty(),"Block posture attacks");ToaSoloPlayableCheck.clear(p);System.out.println("DINH_NATIVE_SPECIAL_50_PERCENT_TWO_MAIN_HITS_NINE_SECONDARY_TARGET_CAP_STAT_DRAIN_AGGRO_AND_BLOCK_PASS");System.exit(0);}}
